"""Opt-in, local durable communication for trusted host adapters.

Routes are consumer-owned, immutable per run. This is an at-least-once inbox,
not an agent launcher, authentication boundary or semantic acceptance engine.
"""
from __future__ import annotations

import argparse
from contextlib import contextmanager
import json
from pathlib import Path
import sqlite3

from scripts.validate_handoff import _load_json, validate


KINDS = {'artifact', 'question', 'review', 'blocker', 'correction'}


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, allow_nan=False,
                      separators=(',', ':'))


def nonblank(value):
    return isinstance(value, str) and bool(value.strip())


def check_plan(plan):
    if not isinstance(plan, dict) or type(plan.get('schema_version')) is not int or plan['schema_version'] != 1:
        raise ValueError('unsupported communication plan')
    if any(not nonblank(plan.get(k)) for k in ('run_id', 'input_version')):
        raise ValueError('run_id and input_version required')
    routes = plan.get('routes')
    if not isinstance(routes, list) or not routes:
        raise ValueError('explicit consumer-owned routes required')
    seen = set()
    for route in routes:
        if not isinstance(route, dict) or any(not nonblank(route.get(k)) for k in ('sender', 'recipient', 'task_id', 'kind')):
            raise ValueError('route needs sender, recipient, task_id and kind')
        key = tuple(route[k] for k in ('sender', 'recipient', 'task_id', 'kind'))
        if route['kind'] not in KINDS or route['sender'] == route['recipient'] or key in seen:
            raise ValueError('invalid, self or duplicate route')
        seen.add(key)
    for key, default in (('max_message_bytes', 8192), ('max_events', 1000)):
        value = plan.get(key, default)
        if type(value) is not int or value < 1:
            raise ValueError(f'{key} must be a positive integer')


class Mailbox:
    def __init__(self, db_path, plan, artifact_root):
        check_plan(plan)
        # Freeze caller data as well as the persisted plan.
        self.plan = json.loads(canonical(plan))
        self.run_id = self.plan['run_id']
        self.root = Path(artifact_root).resolve()
        self.path = Path(db_path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.connect() as db:
            db.executescript('''
                CREATE TABLE IF NOT EXISTS communication_plans (
                    run_id TEXT PRIMARY KEY, body TEXT NOT NULL, root TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS communication_events (
                    seq INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL,
                    event_id TEXT NOT NULL, body TEXT NOT NULL,
                    UNIQUE(run_id,event_id));
                CREATE TABLE IF NOT EXISTS communication_deliveries (
                    seq INTEGER NOT NULL, recipient TEXT NOT NULL, receipt TEXT,
                    PRIMARY KEY(seq,recipient));
            ''')
            db.execute('BEGIN IMMEDIATE')
            db.execute('INSERT OR IGNORE INTO communication_plans VALUES (?,?,?)',
                       (self.run_id, canonical(self.plan), str(self.root)))
            row = db.execute('SELECT body,root FROM communication_plans WHERE run_id=?', (self.run_id,)).fetchone()
            if tuple(row) != (canonical(self.plan), str(self.root)):
                raise ValueError('plan/root changed: create a new run and reconcile outstanding messages')

    @contextmanager
    def connect(self):
        db = sqlite3.connect(self.path, timeout=30)
        db.row_factory = sqlite3.Row
        try:
            with db:
                yield db
        finally:
            db.close()

    def publish(self, event):
        if not isinstance(event, dict):
            raise ValueError('event must be an object')
        required = {'event_id', 'run_id', 'input_version', 'sender', 'task_id',
                    'kind', 'summary', 'action', 'refs'}
        if set(event) != required or any(not nonblank(event.get(k)) for k in required - {'refs'}):
            raise ValueError('event needs exact envelope fields and a concrete action')
        if event['run_id'] != self.run_id or event['input_version'] != self.plan['input_version']:
            raise ValueError('stale or cross-run event')
        recipients = sorted({r['recipient'] for r in self.plan['routes']
                             if all(r[k] == event[k] for k in ('sender', 'task_id', 'kind'))})
        if not recipients:
            raise ValueError('no approved consumer route')
        body = canonical(event)
        if len(body.encode('utf-8')) > self.plan.get('max_message_bytes', 8192):
            raise ValueError('message budget exceeded: put detail in referenced artifacts')
        refs = event['refs']
        if not isinstance(refs, list) or not refs:
            raise ValueError('reference the artifact, question, review or blocker record')
        # Reuse existing path/digest/ID checks instead of a divergent validator.
        errors = validate({'schema_version': 1, 'run_id': self.run_id,
                           'role': event['sender'], 'input_version': event['input_version'],
                           'status': 'partial', 'limitations': ['communication, not completion'],
                           'artifacts': refs, 'checks': [], 'tasks': []}, self.root)
        if errors:
            raise ValueError('; '.join(errors))
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            old = db.execute('SELECT seq,body FROM communication_events WHERE run_id=? AND event_id=?',
                             (self.run_id, event['event_id'])).fetchone()
            if old:
                if old['body'] != body:
                    raise ValueError('event_id reused with different content')
                return {'seq': old['seq'], 'recipients': recipients, 'duplicate': True}
            count = db.execute('SELECT COUNT(*) FROM communication_events WHERE run_id=?', (self.run_id,)).fetchone()[0]
            if count >= self.plan.get('max_events', 1000):
                raise ValueError('run event budget exhausted; reconcile before extending the plan')
            seq = db.execute('INSERT INTO communication_events(run_id,event_id,body) VALUES (?,?,?)',
                             (self.run_id, event['event_id'], body)).lastrowid
            db.executemany('INSERT INTO communication_deliveries(seq,recipient) VALUES (?,?)',
                           [(seq, recipient) for recipient in recipients])
            return {'seq': seq, 'recipients': recipients, 'duplicate': False}

    def inbox(self, recipient, *, limit=20):
        if type(limit) is not int or not 1 <= limit <= 100:
            raise ValueError('limit must be 1..100')
        if recipient not in {r['recipient'] for r in self.plan['routes']}:
            raise ValueError('unknown recipient')
        with self.connect() as db:
            rows = db.execute('''SELECT e.seq,e.body FROM communication_events e
                JOIN communication_deliveries d ON e.seq=d.seq
                WHERE e.run_id=? AND d.recipient=? AND d.receipt IS NULL
                ORDER BY e.seq LIMIT ?''', (self.run_id, recipient, limit)).fetchall()
        return [{'seq': r['seq'], 'event': json.loads(r['body'])} for r in rows]

    def acknowledge(self, recipient, seq, receipt):
        # Receipt records handling, never task completion or scientific validity.
        if type(seq) is not int or not isinstance(receipt, dict) or set(receipt) != {'status', 'reason'}:
            raise ValueError('receipt needs status and reason')
        if receipt['status'] not in ('consumed', 'rejected', 'needs_revision') or not nonblank(receipt['reason']):
            raise ValueError('invalid receipt')
        body = canonical(receipt)
        if len(body.encode('utf-8')) > self.plan.get('max_message_bytes', 8192):
            raise ValueError('receipt budget exceeded')
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute('''SELECT d.receipt FROM communication_deliveries d
                JOIN communication_events e ON e.seq=d.seq
                WHERE e.run_id=? AND d.seq=? AND d.recipient=?''', (self.run_id, seq, recipient)).fetchone()
            if row is None:
                raise ValueError('delivery not found in this run')
            if row['receipt'] is not None and row['receipt'] != body:
                raise ValueError('receipt is immutable; publish a correction event')
            db.execute('UPDATE communication_deliveries SET receipt=? WHERE seq=? AND recipient=?',
                       (body, seq, recipient))

    def status(self):
        with self.connect() as db:
            rows = db.execute('''SELECT e.seq,d.recipient,d.receipt FROM communication_events e
                JOIN communication_deliveries d ON e.seq=d.seq WHERE e.run_id=?
                ORDER BY e.seq,d.recipient''', (self.run_id,)).fetchall()
        return [{'seq': r['seq'], 'recipient': r['recipient'],
                 'receipt': json.loads(r['receipt']) if r['receipt'] else None} for r in rows]

    def consume_handoff(self, recipient, seq, request, *, require_complete=True):
        """Re-read immutable references and validate against trusted consumer scope.

        Returns data without ACK: the host must separately read/verify semantics,
        perform an idempotent action, then acknowledge. A failed check stays pending.
        """
        with self.connect() as db:
            row = db.execute('''SELECT e.body FROM communication_events e
                JOIN communication_deliveries d ON e.seq=d.seq
                WHERE e.run_id=? AND e.seq=? AND d.recipient=?''', (self.run_id, seq, recipient)).fetchone()
        if row is None:
            raise ValueError('delivery not found in this run')
        event = json.loads(row['body'])
        refs = event['refs']
        manifests = [r for r in refs if r['id'] == 'handoff']
        if len(manifests) != 1:
            raise ValueError('handoff reference required')
        ref = manifests[0]
        # Recheck all original references at consumption, including the manifest.
        errors = validate({'schema_version': 1, 'run_id': self.run_id,
                           'role': event['sender'], 'input_version': event['input_version'],
                           'status': 'partial', 'limitations': ['pending consumption'],
                           'artifacts': refs, 'checks': [], 'tasks': []}, self.root)
        if errors:
            raise ValueError('; '.join(errors))
        record = _load_json(self.root / ref['path'])
        errors = validate(record, self.root, require_complete,
                          expected_input_version=self.plan['input_version'], consumer_request=request)
        if isinstance(record, dict) and (record.get('run_id') != self.run_id or record.get('role') != event['sender']):
            errors.append('handoff producer/run mismatch')
        if errors:
            raise ValueError('; '.join(errors))
        return record


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--db', required=True)
    parser.add_argument('--plan', type=Path, required=True)
    parser.add_argument('--root', type=Path, required=True)
    sub = parser.add_subparsers(dest='command', required=True)
    sub.add_parser('status')
    p = sub.add_parser('publish'); p.add_argument('event', type=Path)
    p = sub.add_parser('inbox'); p.add_argument('recipient'); p.add_argument('--limit', type=int, default=20)
    p = sub.add_parser('ack'); p.add_argument('recipient'); p.add_argument('seq', type=int); p.add_argument('receipt', type=Path)
    p = sub.add_parser('consume'); p.add_argument('recipient'); p.add_argument('seq', type=int); p.add_argument('--request', type=Path, required=True)
    args = parser.parse_args()
    try:
        box = Mailbox(args.db, _load_json(args.plan), args.root)
        if args.command == 'publish':
            result = box.publish(_load_json(args.event))
        elif args.command == 'inbox':
            result = box.inbox(args.recipient, limit=args.limit)
        elif args.command == 'ack':
            box.acknowledge(args.recipient, args.seq, _load_json(args.receipt)); result = {'acknowledged': True}
        elif args.command == 'consume':
            result = box.consume_handoff(args.recipient, args.seq, _load_json(args.request))
        else:
            result = box.status()
    except (ValueError, OSError, sqlite3.Error) as exc:
        print(json.dumps({'error': str(exc)}, ensure_ascii=False)); return 1
    print(json.dumps(result, ensure_ascii=False, indent=2)); return 0


if __name__ == '__main__':
    raise SystemExit(main())

"""Durable, bounded task DAG. Trusted host adapters execute; plans never grant rights.

SQLite is the authoritative local ledger (not suitable for shared network FS).
Delivery is at-least-once: adapters must honor stable keys and fencing/cancellation.
No model, shell command, credentials, cloud service or daemon is auto-installed.
"""
from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass
import hashlib
import json
import math
import os
from pathlib import Path
import sqlite3
import stat
import time
from typing import Callable, Protocol
import uuid


def packed(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, allow_nan=False)


def number(value, low, high):
    return (type(value) in (int, float) and math.isfinite(value)
            and low <= value <= high)


def validate(plan):
    if plan.get('schema_version') != 'task-dag/v1':
        raise ValueError('expected task-dag/v1')
    for field in ('run_id', 'user_goal', 'authorization_reference'):
        if not isinstance(plan.get(field), str) or not plan[field].strip():
            raise ValueError(f'missing {field}')
    tasks = plan.get('tasks', [])
    if not isinstance(tasks, list) or not 1 <= len(tasks) <= 1000:
        raise ValueError('1..1000 tasks required')
    ids = [t.get('task_id') for t in tasks]
    if any(not isinstance(i, str) or not i for i in ids) or len(set(ids)) != len(ids):
        raise ValueError('unique nonempty task IDs required')
    for task in tasks:
        for field in ('action', 'owner', 'done_when'):
            if not task.get(field):
                raise ValueError(f'missing {field}')
        deps = task.get('depends_on', [])
        if not isinstance(deps, list) or any(d not in ids for d in deps):
            raise ValueError('unknown dependency')
        if type(task.get('max_attempts')) is not int or not 1 <= task['max_attempts'] <= 20:
            raise ValueError('max_attempts must be 1..20')
        if not number(task.get('estimated_seconds'), 1, 604800):
            raise ValueError('bounded estimated_seconds required')
        if task.get('risk') not in ('low', 'medium', 'high'):
            raise ValueError('risk required')
        if 'wait_policy' in task:
            wait = task['wait_policy']
            if (not isinstance(wait, dict)
                    or set(wait) != {'max_polls', 'max_seconds', 'diagnose_after_seconds'}
                    or type(wait.get('max_polls')) is not int
                    or not 1 <= wait['max_polls'] <= 100000
                    or not number(wait.get('max_seconds'), 1, 604800)
                    or not number(wait.get('diagnose_after_seconds'), 1, wait['max_seconds'])):
                raise ValueError('wait_policy requires bounded polls, elapsed time and diagnosis threshold')
    remaining, visited = {t['task_id']: set(t.get('depends_on', [])) for t in tasks}, set()
    while remaining:
        ready = {i for i, deps in remaining.items() if deps <= visited}
        if not ready:
            raise ValueError('dependency cycle')
        visited |= ready
        remaining = {i: deps for i, deps in remaining.items() if i not in ready}
    policy = plan.get('supervision', {})
    if not (number(policy.get('min_seconds'), 1, 86400)
            and number(policy.get('max_seconds'), policy['min_seconds'], 86400)
            and isinstance(policy.get('rationale'), str) and policy['rationale']):
        raise ValueError('bounded supervision policy with rationale required')
    packed(plan)


def interval(plan, state, changed=False):
    """AI supplies estimates/risk/rationale; deterministic clamp enforces limits."""
    policy = plan['supervision']
    outstanding = [t for t in plan['tasks'] if state['tasks'][t['task_id']]['status'] != 'done']
    estimate = min((t['estimated_seconds'] for t in outstanding), default=policy['min_seconds'])
    risky = any(t['risk'] == 'high' for t in outstanding)
    base = estimate * (0.1 if risky else 0.25)
    backoff = 1 if changed else 2 ** min(state.get('idle_ticks', 0), 10)
    return min(policy['max_seconds'], max(policy['min_seconds'], base * backoff))


def wait_limit(task, node, now):
    """Explicit opt-in observation budget; legacy plans retain attempt semantics."""
    policy = task.get('wait_policy')
    if policy is None or 'pending_since' not in node:
        return None
    if node.get('pending_polls', 0) >= policy['max_polls']:
        return 'pending observation budget exhausted; main AI diagnosis required'
    if now - node['pending_since'] >= policy['max_seconds']:
        return 'pending elapsed budget exhausted; main AI diagnosis required'
    return None


class Store:
    def __init__(self, path):
        self.path = str(Path(path).resolve())
        Path(self.path).parent.mkdir(parents=True, exist_ok=True)
        with self.transaction() as db:
            db.execute('CREATE TABLE IF NOT EXISTS chains (id TEXT PRIMARY KEY, plan TEXT, state TEXT)')
            db.execute('CREATE TABLE IF NOT EXISTS events (chain_id TEXT, event_id TEXT, at REAL, PRIMARY KEY(chain_id,event_id))')
            db.execute('CREATE TABLE IF NOT EXISTS journal (seq INTEGER PRIMARY KEY, chain_id TEXT, at REAL, kind TEXT, detail TEXT)')
            db.execute('CREATE TABLE IF NOT EXISTS monitors (id TEXT PRIMARY KEY, chain_id TEXT UNIQUE, status TEXT, due REAL)')
            if 'version' not in {row['name'] for row in db.execute('PRAGMA table_info(monitors)')}:
                db.execute('ALTER TABLE monitors ADD COLUMN version INTEGER NOT NULL DEFAULT 0')
            db.execute('CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, expires REAL)')

    @contextmanager
    def transaction(self):
        db = sqlite3.connect(self.path, timeout=30, isolation_level=None)
        db.row_factory = sqlite3.Row
        try:
            db.execute('PRAGMA synchronous=FULL')
            db.execute('BEGIN IMMEDIATE')
            yield db
            db.commit()
        except BaseException:
            db.rollback()
            raise
        finally:
            db.close()

    def load(self, db, run_id):
        row = db.execute('SELECT plan,state FROM chains WHERE id=?', (run_id,)).fetchone()
        if row is None:
            raise KeyError(run_id)
        return json.loads(row['plan']), json.loads(row['state'])

    def save(self, db, run_id, state):
        db.execute('UPDATE chains SET state=? WHERE id=?', (packed(state), run_id))

    def log(self, db, run_id, now, kind, detail):
        db.execute('INSERT INTO journal(chain_id,at,kind,detail) VALUES (?,?,?,?)',
                   (run_id, now, kind, packed(detail)))

    def create(self, plan):
        validate(plan)
        state = {'status': 'active', 'idle_ticks': 0, 'tasks': {
            t['task_id']: {'status': 'todo', 'attempts': 0, 'next_at': 0,
                           'evidence': [], 'reason': None} for t in plan['tasks']}}
        with self.transaction() as db:
            old = db.execute('SELECT plan FROM chains WHERE id=?', (plan['run_id'],)).fetchone()
            if old:
                if old['plan'] != packed(plan):
                    raise ValueError('run_id already bound to a different immutable plan')
                return plan['run_id']
            db.execute('INSERT INTO chains VALUES (?,?,?)', (plan['run_id'], packed(plan), packed(state)))
        return plan['run_id']

    def snapshot(self, run_id):
        with self.transaction() as db:
            plan, state = self.load(db, run_id)
            row = db.execute('SELECT * FROM monitors WHERE chain_id=?', (run_id,)).fetchone()
            return {'plan': plan, 'state': state, 'monitor': dict(row) if row else None}

    def cancel(self, run_id, reference, now=None):
        if not reference:
            raise ValueError('cancellation instruction reference required')
        with self.transaction() as db:
            _, state = self.load(db, run_id)
            state['status'] = 'cancelled'
            for node in state['tasks'].values():
                if node['status'] != 'done':
                    node.update(status='cancelled', reason=reference, token=None, diagnosis_required=False)
            self.save(db, run_id, state)
            db.execute("UPDATE monitors SET status='stopped' WHERE chain_id=?", (run_id,))
            self.log(db, run_id, time.time() if now is None else now, 'cancel', reference)


@dataclass
class Outcome:
    status: str  # complete candidate / pending observation / retry / blocked / failed
    reason: str = ''
    evidence: list | None = None


@dataclass
class Context:
    store: Store
    run_id: str
    task_id: str
    token: str
    idempotency_key: str
    clock: Callable

    def current(self):
        snap = self.store.snapshot(self.run_id)['state']
        node = snap['tasks'][self.task_id]
        return (snap['status'] != 'cancelled' and node.get('token') == self.token
                and node['status'] == 'doing' and node['lease_until'] > self.clock())


class Handler(Protocol):
    # Trusted adapter metadata, never accepted from the model's plan.
    idempotent: bool
    required_capabilities: frozenset[str]

    def run(self, task: dict, context: Context) -> Outcome: ...
    def verify(self, task: dict, evidence: list) -> bool: ...


class Engine:
    def __init__(self, store, handlers, authorize=None, clock=time.time, lease_seconds=300):
        if not number(lease_seconds, 1, 86400):
            raise ValueError('invalid lease')
        self.store, self.handlers = store, handlers
        self.authorize = authorize or (lambda plan, task, handler: False)
        self.clock, self.lease_seconds = clock, lease_seconds

    def _authorized(self, plan, task, handler):
        try:
            return self.authorize(plan, task, handler) is True
        except Exception:
            # An unavailable policy service must not grant rights or kill monitor.
            return False

    def _check_done(self, plan, state):
        # Fresh dependency/terminal evidence, not just an old success bit.
        for task in plan['tasks']:
            node = state['tasks'][task['task_id']]
            if node['status'] != 'done':
                continue
            handler = self.handlers.get(task['action'])
            try:
                valid = handler is not None and handler.verify(task, node['evidence'])
            except Exception:
                valid = False
            if not valid:
                node.update(status='failed', reason='previous completion evidence no longer valid')
        # Invalidation follows dependency closure, even when plan order is not
        # topological. A valid file cannot justify results built on invalid inputs.
        changed = True
        while changed:
            changed = False
            for task in plan['tasks']:
                node = state['tasks'][task['task_id']]
                if (node['status'] == 'done' and any(state['tasks'][d]['status'] != 'done'
                                                    for d in task.get('depends_on', []))):
                    node.update(status='failed', reason='completed result depends on invalid evidence')
                    changed = True

    def reconcile(self, run_id, task_id, evidence, reference):
        """Explicit host reconciliation of an ambiguous effect; no blind replay."""
        if not reference or not evidence:
            raise ValueError('reconciliation evidence and host reference required')
        with self.store.transaction() as db:
            plan, state = self.store.load(db, run_id)
            task = next(t for t in plan['tasks'] if t['task_id'] == task_id)
            node, handler = state['tasks'][task_id], self.handlers.get(task['action'])
            if state['status'] == 'cancelled' or node['status'] != 'blocked':
                raise ValueError('only blocked, non-cancelled tasks may be reconciled')
            if (handler is None or not self._authorized(plan, task, handler)
                    or not all(state['tasks'][d]['status'] == 'done' for d in task.get('depends_on', []))
                    or not handler.verify(task, evidence)):
                raise ValueError('reconciliation not authorized or not verified')
            node.update(status='done', token=None, evidence=evidence, reason=reference, diagnosis_required=False)
            self._check_done(plan, state)
            self._summary(plan, state)
            self.store.save(db, run_id, state)
            if state['status'] == 'done':
                db.execute("UPDATE monitors SET status='stopped' WHERE chain_id=?", (run_id,))
            self.store.log(db, run_id, self.clock(), 'reconcile', {'task_id': task_id, 'reference': reference})
            return state

    def _summary(self, plan, state):
        if state['status'] == 'cancelled':
            return
        nodes = state['tasks']
        for task in plan['tasks']:
            node = nodes[task['task_id']]
            if node['status'] in ('todo', 'blocked'):
                bad = [d for d in task.get('depends_on', [])
                       if nodes[d]['status'] in ('failed', 'blocked', 'cancelled')]
                if bad and node.get('reason_kind') != 'permission':
                    node.update(status='blocked', reason='dependencies: ' + ', '.join(bad), reason_kind='dependency')
                elif not bad and node.get('reason_kind') == 'dependency':
                    node.update(status='todo', reason=None, reason_kind=None)
        statuses = [n['status'] for n in nodes.values()]
        if all(s == 'done' for s in statuses):
            state['status'] = 'done'
        elif any(s in ('todo', 'doing') for s in statuses):
            state['status'] = 'active'
        elif 'failed' in statuses:
            state['status'] = 'failed'
        else:
            state['status'] = 'blocked'

    def tick(self, run_id, event_id):
        """Only trusted host wake-ups call this API. Event text in documents is not a trigger.

        One claim per tick bounds work; successor readiness is durable for next wake-up.
        An early/duplicate tick cannot bypass retry deadlines or active leases.
        """
        if not isinstance(event_id, str) or not event_id:
            raise ValueError('event ID required')
        now, claim = self.clock(), None
        with self.store.transaction() as db:
            plan, state = self.store.load(db, run_id)
            if state['status'] in ('done', 'cancelled'):
                return state
            if db.execute('SELECT 1 FROM events WHERE chain_id=? AND event_id=?', (run_id, event_id)).fetchone():
                return state
            db.execute('INSERT INTO events VALUES (?,?,?)', (run_id, event_id, now))
            self._check_done(plan, state)
            for task in plan['tasks']:
                node = state['tasks'][task['task_id']]
                handler = self.handlers.get(task['action'])
                if node['status'] == 'doing' and node['lease_until'] <= now:
                    if handler and handler.idempotent:
                        node.update(status='todo' if node['attempts'] < task['max_attempts'] else 'failed',
                                    token=None, next_at=now, reason='expired lease; retry uses original idempotency key')
                    else:
                        node.update(status='blocked', token=None, reason_kind='ambiguous',
                                    reason='expired lease: external side effect unknown; reconciliation required')
                if node.get('reason_kind') in ('permission', 'adapter'):
                    node.update(status='todo', reason_kind=None)
                if (task.get('wait_policy') and 'pending_since' in node
                        and node['status'] in ('todo', 'doing', 'blocked')
                        and now - node['pending_since'] >= task['wait_policy']['diagnose_after_seconds']):
                    # Observation diagnostics must not wait for another action claim.
                    node['diagnosis_required'] = True
            self._summary(plan, state)
            tasks = plan['tasks']
            cursor = state.get('claim_cursor', 0) % len(tasks)
            for offset in range(len(tasks)):
                index = (cursor + offset) % len(tasks)
                task = tasks[index]
                node = state['tasks'][task['task_id']]
                if node['status'] != 'todo':
                    continue
                if not all(state['tasks'][d]['status'] == 'done' for d in task.get('depends_on', [])):
                    continue
                exhausted = wait_limit(task, node, now)
                if exhausted:
                    node.update(status='blocked', reason_kind='wait_budget', reason=exhausted,
                                diagnosis_required=True)
                    continue
                if node['next_at'] > now:
                    continue
                handler = self.handlers.get(task['action'])
                if handler is None:
                    node.update(status='blocked', reason_kind='adapter', reason='host action adapter unavailable')
                    continue
                if not self._authorized(plan, task, handler):
                    node.update(status='blocked', reason_kind='permission', reason='host authorization required')
                    continue
                token = uuid.uuid4().hex
                node.update(status='doing', attempts=node['attempts'] + 1, token=token,
                            lease_until=now + self.lease_seconds, reason=None, reason_kind=None,
                            dispatches=node.get('dispatches', 0) + 1)
                # Persist fairness across restarts and concurrent claimants.
                # Readiness, authorization and individual deadlines still gate each claim.
                state['claim_cursor'] = (index + 1) % len(tasks)
                key = hashlib.sha256((packed(plan) + '\0' + task['task_id']).encode()).hexdigest()
                claim = (task, handler, Context(self.store, run_id, task['task_id'], token, key, self.clock))
                break
            # Claims/permission rechecks are not progress. Only verified results
            # (or an explicit change event) reset backoff; pending/retry grows it.
            if not claim:
                state['idle_ticks'] += 1
            self._summary(plan, state)
            state['next_check_seconds'] = interval(plan, state)
            self.store.save(db, run_id, state)
            self.store.log(db, run_id, now, 'tick', {'event_id': event_id, 'claimed': claim[0]['task_id'] if claim else None})
        if claim:
            task, handler, context = claim
            try:
                if not context.current() or not self._authorized(plan, task, handler):
                    outcome = Outcome('blocked', 'authorization revoked or claim no longer current')
                else:
                    outcome = handler.run(task, context)
                    if outcome.status == 'complete' and not (outcome.evidence and handler.verify(task, outcome.evidence)):
                        outcome = Outcome('failed', 'completion evidence rejected by verifier')
                    if outcome.status not in ('complete', 'pending', 'retry', 'blocked', 'failed'):
                        outcome = Outcome('failed', 'invalid adapter outcome')
            except Exception as exc:
                # Unknown side effects: only an explicitly idempotent adapter may retry.
                outcome = Outcome('retry' if handler.idempotent else 'blocked',
                                  f'adapter exception {type(exc).__name__}: {exc}')
            with self.store.transaction() as db:
                plan, state = self.store.load(db, run_id)
                node = state['tasks'][task['task_id']]
                if (node.get('token') == context.token and node['status'] == 'doing'
                        and node['lease_until'] > self.clock() and state['status'] != 'cancelled'):
                    status = {'complete': 'done', 'pending': 'todo', 'retry': 'todo'}.get(outcome.status, outcome.status)
                    reason_kind = 'adapter_result'
                    if outcome.status == 'pending' and task.get('wait_policy') is not None:
                        # Only a successfully returned observation refunds this claim.
                        # Crashes, unknown side effects and retry outcomes still cost attempts.
                        node['attempts'] -= 1
                        node['pending_polls'] = node.get('pending_polls', 0) + 1
                        node.setdefault('pending_since', now)
                        node['last_pending_at'] = self.clock()
                        node['diagnosis_required'] = (
                            self.clock() - node['pending_since'] >= task['wait_policy']['diagnose_after_seconds'])
                        exhausted = wait_limit(task, node, self.clock())
                        if exhausted:
                            status, reason_kind = 'blocked', 'wait_budget'
                            outcome.reason = exhausted
                            node['diagnosis_required'] = True
                    if status == 'todo' and node['attempts'] >= task['max_attempts']:
                        status = 'failed'
                        outcome.reason = 'attempt budget exhausted: ' + outcome.reason
                    node.update(status=status, token=None, reason=outcome.reason,
                                evidence=outcome.evidence or [], reason_kind=reason_kind)
                    if status == 'done':
                        node['diagnosis_required'] = False
                    state['idle_ticks'] = state['idle_ticks'] + 1 if status == 'todo' else 0
                    delay = interval(plan, state, status == 'done')
                    node['next_at'] = self.clock() + delay
                    self._check_done(plan, state)
                    self._summary(plan, state)
                    state['next_check_seconds'] = interval(plan, state, status == 'done')
                    self.store.save(db, run_id, state)
                    self.store.log(db, run_id, self.clock(), 'outcome', {'task_id': task['task_id'], 'status': status, 'reason': outcome.reason})
                else:
                    self.store.log(db, run_id, self.clock(), 'stale_result_rejected', {'task_id': task['task_id']})
        with self.store.transaction() as db:
            _, state = self.store.load(db, run_id)
            if state['status'] in ('done', 'cancelled', 'failed'):
                db.execute("UPDATE monitors SET status='stopped' WHERE chain_id=?", (run_id,))
            return state


class ArtifactHandler:
    """Read-only, content-hash acceptance. Does not do semantic/LLM verification."""
    idempotent = True
    required_capabilities = frozenset({'read_artifacts'})

    def __init__(self, root):
        self.root = Path(root).resolve()

    def _evidence(self, task):
        results = []
        for item in task['done_when']['artifacts']:
            path = (self.root / item['path']).resolve()
            if not path.is_relative_to(self.root):
                raise ValueError('artifact outside authorized root')
            # A FIFO/device is not an artifact. Nonblocking open plus fstat avoids
            # blocking before validation; read(limit+1) also bounds concurrent growth.
            flags = os.O_RDONLY | getattr(os, 'O_NONBLOCK', 0) | getattr(os, 'O_NOFOLLOW', 0)
            fd = os.open(path, flags)
            with os.fdopen(fd, 'rb') as stream:
                metadata = os.fstat(stream.fileno())
                if not stat.S_ISREG(metadata.st_mode):
                    raise ValueError('artifact must be a regular file')
                limit = 16 * 1024 * 1024
                if metadata.st_size > limit:
                    raise ValueError('artifact exceeds 16 MiB verification bound')
                content = stream.read(limit + 1)
                if len(content) > limit:
                    raise ValueError('artifact grew beyond verification bound')
            digest = hashlib.sha256(content).hexdigest()
            if digest != item['sha256']:
                raise ValueError('artifact digest does not match predeclared acceptance')
            results.append({'path': item['path'], 'sha256': digest})
        return results

    def run(self, task, context):
        try:
            return Outcome('complete', evidence=self._evidence(task))
        except FileNotFoundError:
            return Outcome('pending', 'artifact not yet present')

    def verify(self, task, evidence):
        return bool(evidence) and evidence == self._evidence(task)

#!/usr/bin/env python3
"""Validate local handoff integrity, not truth or LLM compliance. No network."""
from __future__ import annotations

import argparse
from collections import deque
import hashlib
import json
from pathlib import Path


def _sha256_file(path: Path) -> str:
    """Hash stable local artifacts with bounded Python allocation, including short reads."""
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while chunk := stream.read(1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def _load_json(path: Path):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError(f"duplicate JSON key: {key}")
            result[key] = value
        return result
    def constant(value):
        raise ValueError(f"non-finite JSON number: {value}")
    return json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=pairs,
                      parse_constant=constant)


def _consumer_contract(request: object) -> tuple[str | None, dict[str, bool], list[str]]:
    """Parse independently supplied scope. Producer fields never authorize skips."""
    errors = []
    if not isinstance(request, dict):
        return None, {}, ["consumer request must be an object"]
    if type(request.get("schema_version")) is not int or request["schema_version"] != 1:
        errors.append("unsupported consumer request schema_version")
    version = request.get("input_version")
    if not isinstance(version, str) or not version.strip():
        errors.append("consumer request input_version must be nonblank text")
        version = None
    tasks = request.get("tasks")
    if not isinstance(tasks, list):
        return version, {}, errors + ["consumer request tasks must be an explicit list"]
    expected = {}
    for index, task in enumerate(tasks):
        if not isinstance(task, dict):
            errors.append(f"consumer task {index} must be an object")
            continue
        tid = task.get("task_id")
        if not isinstance(tid, str) or not tid.strip() or tid in expected:
            errors.append(f"consumer task {index}: missing/duplicate task_id")
            continue
        allowed = task.get("allow_skip", False)
        if type(allowed) is not bool:
            errors.append(f"consumer task {index}: allow_skip must be boolean")
            allowed = False
        expected[tid] = allowed
    return version, expected, errors


def validate(record: dict, root: Path, require_complete: bool = False, *,
             expected_input_version: str | None = None,
             consumer_request: dict | None = None) -> list[str]:
    errors = []
    try:
        root = root.resolve()
    except (OSError, ValueError, RuntimeError) as exc:
        return [f"root: cannot resolve path ({type(exc).__name__})"]
    if not isinstance(record, dict):
        return ["handoff must be an object"]
    if type(record.get("schema_version")) is not int or record["schema_version"] != 1:
        errors.append("unsupported schema_version")
    for key in ("run_id", "role", "input_version"):
        if not isinstance(record.get(key), str) or not record[key].strip():
            errors.append(f"missing {key}")
    # Consumer intent is an independent input, never inferred from producer claims.
    expected_tasks = None
    if consumer_request is not None:
        version, expected_tasks, contract_errors = _consumer_contract(consumer_request)
        errors.extend(contract_errors)
        if expected_input_version is not None and expected_input_version != version:
            errors.append("consumer request conflicts with expected input version")
        if expected_input_version is None:
            expected_input_version = version
    elif require_complete:
        errors.append("unverified: consumer request required for completion")
    if expected_input_version is not None:
        if not isinstance(expected_input_version, str) or not expected_input_version.strip():
            errors.append("consumer input version must be a nonblank string")
        elif record.get("input_version") != expected_input_version:
            errors.append("consumer input version mismatch")
    elif require_complete:
        errors.append("unverified: expected consumer input version required for completion")
    status = record.get("status")
    if not isinstance(status, str) or status not in {"completed", "partial", "blocked", "failed", "not_run"}:
        errors.append("invalid status")
    if require_complete and status != "completed":
        errors.append("completion gate: run is not completed")
    limitations = record.get("limitations")
    if not isinstance(limitations, list) or any(not isinstance(x, str) for x in limitations):
        errors.append("limitations must be a list of strings")
    elif status != "completed" and not limitations:
        errors.append("non-completed run needs limitations/recovery conditions")

    artifacts = record.get("artifacts")
    if not isinstance(artifacts, list):
        errors.append("artifacts must be a list")
        artifacts = []
    if status == "completed" and not artifacts:
        errors.append("completed run needs an artifact (a saved answer is sufficient)")
    artifact_ids = set()
    for index, artifact in enumerate(artifacts):
        if not isinstance(artifact, dict):
            errors.append(f"artifact {index} must be an object")
            continue
        aid = artifact.get("id")
        if not isinstance(aid, str) or not aid.strip() or aid in artifact_ids:
            errors.append(f"artifact {index}: missing/duplicate id")
        else:
            artifact_ids.add(aid)
        raw = artifact.get("path")
        if not isinstance(raw, str) or not raw.strip() or "\0" in raw or Path(raw).is_absolute():
            errors.append(f"artifact {index}: path must be relative to root")
            continue
        try:
            path = (root / raw).resolve()
            if not path.is_relative_to(root):
                errors.append(f"artifact {index}: path escapes root")
                continue
            if not path.is_file():
                errors.append(f"artifact {index}: file missing")
                continue
            digest = _sha256_file(path)
        except (OSError, ValueError, RuntimeError) as exc:
            errors.append(f"artifact {index}: cannot read path ({type(exc).__name__})")
            continue
        if artifact.get("sha256") != digest:
            errors.append(f"artifact {index}: sha256 mismatch")

    checks = record.get("checks")
    if not isinstance(checks, list):
        errors.append("checks must be a list")
        checks = []
    if status == "completed" and not checks:
        errors.append("completed run needs acceptance checks")
    for index, check in enumerate(checks):
        if not isinstance(check, dict):
            errors.append(f"check {index} must be an object")
            continue
        if not isinstance(check.get("criterion"), str) or not check["criterion"].strip() or not isinstance(check.get("status"), str) or check["status"] not in {"pass", "fail", "not_run"}:
            errors.append(f"check {index}: criterion/status required")
        refs = check.get("artifact_ids")
        if not isinstance(refs, list) or any(not isinstance(x, str) or x not in artifact_ids for x in refs):
            errors.append(f"check {index}: invalid evidence references")
        elif check.get("status") == "pass" and not refs:
            errors.append(f"check {index}: pass without evidence")
        if status == "completed" and check.get("status") != "pass":
            errors.append(f"check {index}: incomplete check on completed run")

    tasks = record.get("tasks", [])
    if not isinstance(tasks, list):
        errors.append("tasks must be a list")
        tasks = []
    by_id = {}
    for task in tasks:
        if not isinstance(task, dict) or not isinstance(task.get("task_id"), str) or not task["task_id"].strip():
            errors.append("task missing task_id")
            continue
        tid = task["task_id"]
        if tid in by_id:
            errors.append(f"duplicate task: {tid}")
        by_id[tid] = task
    if expected_tasks is not None:
        for tid in sorted(expected_tasks.keys() - by_id.keys()):
            errors.append(f"consumer task missing: {tid}")
        for tid in sorted(by_id.keys() - expected_tasks.keys()):
            errors.append(f"task outside consumer scope: {tid}")
        for tid in expected_tasks.keys() & by_id.keys():
            if by_id[tid].get("status") == "skipped" and not expected_tasks[tid]:
                errors.append(f"{tid}: skip not authorized by consumer")
    graph = {}
    for tid, task in by_id.items():
        deps = task.get("depends_on", [])
        if not isinstance(deps, list) or any(not isinstance(x, str) for x in deps):
            errors.append(f"{tid}: invalid dependencies")
            deps = []
        graph[tid] = deps
        if not isinstance(task.get("status"), str) or task["status"] not in {"todo", "doing", "done", "blocked", "skipped"}:
            errors.append(f"{tid}: invalid task status")
        if status == "completed" and task.get("status") not in ("done", "skipped"):
            errors.append(f"{tid}: unfinished task on completed run")
        for dep in deps:
            if dep not in by_id:
                errors.append(f"{tid}: unknown dependency {dep}")
            elif task.get("status") == "done" and by_id[dep].get("status") != "done":
                errors.append(f"{tid}: done before dependency {dep}")
        evidence = task.get("evidence", [])
        if not isinstance(evidence, list) or any(not isinstance(x, str) or x not in artifact_ids for x in evidence):
            errors.append(f"{tid}: invalid evidence references")
        elif task.get("status") == "done" and not evidence:
            errors.append(f"{tid}: done without evidence")
        reason = task.get("reason")
        if task.get("status") in ("blocked", "skipped") and (not isinstance(reason, str) or not reason.strip()):
            errors.append(f"{tid}: reason/recovery required")
    # Kahn elimination visits each known vertex/edge once; no repeated whole-DAG
    # scans or recursion. As above, unknown dependencies have their own diagnostic.
    # Duplicate dependencies count once here, matching the former set elimination.
    remaining = {}
    dependents = {tid: [] for tid in graph}
    for tid, deps in graph.items():
        known = {dep for dep in deps if dep in graph}
        remaining[tid] = len(known)
        for dep in known:
            dependents[dep].append(tid)
    ready = deque(tid for tid, count in remaining.items() if count == 0)
    removed = 0
    while ready:
        tid = ready.popleft()
        removed += 1
        for dependent in dependents[tid]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                ready.append(dependent)
    if removed != len(graph):
        errors.append("task dependency cycle")
    return errors


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("record", type=Path)
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--require-complete", action="store_true")
    parser.add_argument("--expected-input-version",
                        help="trusted consumer version for integrity checks; must match --request if both supplied")
    parser.add_argument("--request", type=Path,
                        help="trusted consumer JSON with input_version and complete tasks list; required for completion")
    args = parser.parse_args()
    try:
        record = _load_json(args.record)
        request = _load_json(args.request) if args.request else None
        if args.request and not isinstance(request, dict):
            raise ValueError("consumer request must be an object")
        errors = validate(record, args.root, args.require_complete,
                          expected_input_version=args.expected_input_version,
                          consumer_request=request)
    except (OSError, ValueError) as exc:
        errors = [str(exc)]
    print(json.dumps({"integrity_valid": not errors, "errors": errors,
                      "completion_verified": not errors and args.require_complete,
                      "consumer_version_checked": not errors and (args.expected_input_version is not None or args.request is not None),
                      "consumer_scope_verified": not errors and args.request is not None,
                      "scope": "local integrity and explicit consumer contract only; no semantic or visual certification"}, ensure_ascii=False, indent=2))
    return 1 if errors else 0


if __name__ == "__main__":
    raise SystemExit(main())
